/**
 * Sorted requests for calculation discrepancies.
 * Web copy of shared/calculationDiscrepancies.js. Keep the two files in sync.
 */
import { isEstimateOrMiscellaneousTransaction } from './estimateScreeningPolicy';

const QUANTITY_PATTERNS = [
  { pattern: /(\d+(?:\.\d+)?)\s*(?:litres|liters|litre|liter|ltr)\b/i, unit: 'liter' },
  { pattern: /(\d+(?:\.\d+)?)\s*(kwh|kw-h)\b/i, unit: 'kWh' },
  { pattern: /(\d+(?:\.\d+)?)\s*kg\b/i, unit: 'kg' },
  { pattern: /(\d+(?:\.\d+)?)\s*(?:tonne-km|ton-km|tonkm)\b/i, unit: 'tonne-km' }
];

const statedQuantity = (transaction = {}) => {
  const text = `${transaction.description || ''} ${transaction.memo || ''} ${transaction.narration || ''}`;
  for (const entry of QUANTITY_PATTERNS) {
    const match = text.match(entry.pattern);
    if (!match) continue;
    const quantity = Number(match[1]);
    if (quantity > 0) return { quantity, unit: entry.unit };
  }
  return null;
};

const footprintOf = (transaction = {}, footprint = null) => (
  footprint && typeof footprint === 'object'
    ? footprint
    : (transaction.carbonFootprint || {})
);

const scopeOf = (transaction = {}, footprint = {}) => (
  transaction.scopeClassification
  || footprint.scopeClassification
  || null
);

const item = (fields) => ({
  id: fields.id,
  severity: fields.severity,
  order: fields.order || 0,
  title: fields.title,
  request: fields.request,
  field: fields.field || null
});

export const collectCalculationDiscrepancies = (transaction = {}, footprint = null) => {
  const fp = footprintOf(transaction, footprint);
  const items = [];
  const validation = fp.calculationRecord?.validation;
  if (validation && validation.withinTolerance === false) {
    const difference = Number(validation.differenceKgCo2e);
    const calculated = validation.reportedKgCo2e != null && Number.isFinite(difference)
      ? Number(validation.reportedKgCo2e) + difference
      : fp.calculationRecord?.results?.calculatedKgCo2e;
    items.push(item({
      id: 'formula_mismatch',
      severity: 1,
      order: Math.abs(Number.isFinite(difference) ? difference : 0),
      title: 'Calculated kilograms do not match the stored result',
      field: 'activity_quantity',
      request: `Add the quantity, unit, and factor source from the bill. The formula gives ${calculated ?? '—'} kg CO₂e and the stored ${validation.comparedTo || 'inventory'} figure is ${validation.reportedKgCo2e ?? '—'} kg CO₂e (difference ${validation.differenceKgCo2e ?? '—'} kg, tolerance ${validation.toleranceKgCo2e ?? '—'} kg).`
    }));
  }

  const scope = scopeOf(transaction, fp);
  const questions = Array.isArray(scope?.questions) ? scope.questions : [];
  if (scope?.status === 'needs_input') {
    if (questions.length === 0) {
      items.push(item({
        id: 'scope_unresolved',
        severity: 2,
        title: 'Scope is not settled',
        field: 'fuel_combustion_control',
        request: 'Add who operates this activity. Company-operated combustion is Scope 1. Contractor freight is Scope 3. The row stays out of the inventory until you add that detail.'
      }));
    }
    questions.forEach((question, index) => {
      items.push(item({
        id: `scope_${question.id || index}`,
        severity: 2,
        order: index,
        title: question.prompt || 'Missing scope detail',
        field: question.id || null,
        request: `Add ${question.prompt || 'the missing scope detail'}. ${question.detail || ''}`.trim()
      }));
    });
  }

  const checks = Array.isArray(transaction.metadata?.billCrossCheck?.checks)
    ? transaction.metadata.billCrossCheck.checks
    : [];
  checks.forEach((check, index) => {
    if (!check || (check.status !== 'mismatch' && check.status !== 'missing_on_bill')) return;
    const mismatch = check.status === 'mismatch';
    items.push(item({
      id: `bill_${check.field || index}`,
      severity: mismatch ? 3 : 4,
      order: index,
      title: mismatch
        ? `Bill ${check.field || 'field'} does not match`
        : `Bill is missing ${check.field || 'a field'}`,
      field: check.field || null,
      request: `Add the ${check.field || 'matching detail'} from the bill. ${check.message || 'The bill and this calculation disagree.'}`
    }));
  });

  const learned = fp.learnedMeasurement || transaction.metadata?.learnedMeasurement;
  const stated = statedQuantity(transaction);
  if (learned?.quantity > 0 && stated && stated.unit === learned.unit) {
    const gap = Math.abs(stated.quantity - Number(learned.quantity)) / stated.quantity;
    if (gap > 0.05) {
      items.push(item({
        id: 'learned_quantity_disagrees',
        severity: 3,
        order: 10 + gap,
        title: 'Learned quantity does not match this bill',
        field: 'activity_quantity',
        request: `Add the quantity printed on this bill. The calculation used ${learned.quantity} ${learned.unit} from earlier bills, and this description shows ${stated.quantity} ${stated.unit}.`
      }));
    }
  }

  if (isEstimateOrMiscellaneousTransaction({ ...transaction, carbonFootprint: fp }).match) {
    items.push(item({
      id: 'estimate_needs_detail',
      severity: 5,
      title: 'This row is still an estimate',
      field: 'activity_quantity',
      request: 'Add the activity quantity and unit from the bill for an activity-based calculation, or add the unit price for a spend-based calculation. An estimate is not kept once that detail is on the row.'
    }));
  }

  const flags = Array.isArray(fp.complianceFlags) ? fp.complianceFlags : [];
  const scopeAlreadyAsksControl = questions.some((question) => (
    question.id === 'fuel_combustion_control' || question.id === 'transport_control'
  ));
  if (flags.includes('mobile_combustion_ownership_unspecified') && !scopeAlreadyAsksControl) {
    items.push(item({
      id: 'ownership_unspecified',
      severity: 6,
      title: 'Vehicle or fuel control is missing',
      field: 'transport_control',
      request: 'Add whether your company operates this vehicle or fuel. Operated by you is Scope 1. A contractor is Scope 3.'
    }));
  }

  return items.sort((left, right) => (
    left.severity - right.severity
    || left.order - right.order
    || String(left.id).localeCompare(String(right.id))
  ));
};
